import * as React from "react"

function BuyMeACoffeeCtaSection({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="buy-me-a-coffee-cta-section"
      className={className}
      {...props}
    >
      <div className="bg-gray-100 dark800 py-8 px-4 sm6 lg8">
          <div className="max-w-7xl mx-auto">
              <div className="max-w-3xl mx-auto text-center">
                  <h2 className="text-3xl font-extrabold text-gray-900 dark sm4xl">
                      Enjoying my content?
                  </h2>
                  <p className="mt-3 text-xl text-gray-500 dark400 sm4">
                      Consider buying me a coffee to support my work!
                  </p>
                  <div className="mt-8">
                      <img className="mx-auto h-14" src="https://cdn.buymeacoffee.com/buttons/v2/default-yellow.png" alt="Buy Me a Coffee" />
                  </div>
              </div>
          </div>
      </div>
    </div>
  )
}

export { BuyMeACoffeeCtaSection }
